package bot

import "strconv"

func answerToLetter(answer string) string {
	switch answer {
	case "answer1":
		return "A"
	case "answer2":
		return "B"
	}

	return ""
}

func buildChain(userID int64) string {
	var chain string
	count := len(NewQuestions())

	for i := 0; i < count; i++ {
		if i > 0 {
			chain += "-"
		}

		letter := answerToLetter(answers[userID][i])
		chain += letter
	}
	return chain
}

func shopLabel(shop CoffeeShop) string {
	return shop.Name + " — " + shop.Address
}

func findShop(shops []CoffeeShop, label string) (CoffeeShop, bool) {
	for _, shop := range shops {
		if shopLabel(shop) == label {
			return shop, true
		}
	}
	return CoffeeShop{}, false
}

var recommendedShops = make(map[int64][]CoffeeShop)
var currentShop = make(map[int64]int)

func loadRecommendations(userID int64) []CoffeeShop {
	labels := recommendations[buildChain(userID)]
	all := NewCoffeeShop()
	var shops []CoffeeShop

	for _, label := range labels {
		shop, ok := findShop(all, label)
		if !ok {
			shop = CoffeeShop{Name: label}
		}
		shops = append(shops, shop)
	}
	return shops
}

func shopCardText(userID int64) string {
	shops := recommendedShops[userID]
	index := currentShop[userID]
	shop := shops[index]
	header := strconv.Itoa(index+1) + "/" + strconv.Itoa(len(shops)) + "\n"

	if shop.Description == "" {
		return header + shop.Name
	}
	return header + shop.Name + " — " + shop.Address + "\n\n" + shop.Description
}

